package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import static com.ruoyi.ai.agent.AgentJson.*;
public class B9ResultSheetMysqlTest extends TestCase {
    private A1TestFixture f;private AgentStore store;private ControlledWriteService writes;private ObjectNode source,snapshot,request;private long book;
    protected void setUp() throws Exception {
        f=new A1TestFixture();store=new AgentStore(f.db);String sql=new String(Files.readAllBytes(Paths.get(System.getProperty("a1.module"),"sql/ai_agent_controlled_write_v2.sql")),StandardCharsets.UTF_8);f.db.execute(sql.replaceAll("(?m)^--[^\\r\\n]*","").trim());writes=new ControlledWriteService(store,f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());for(String field:new String[]{"enabled","b8EffectEnabled","b9ResultEnabled","b8SheetEnabled","b9ResultSheetEnabled"})A1TestFixture.inject(writes,field,true);
        snapshot=(ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\",\"out\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Source\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"Name\"},\"1\":{\"v\":\"Amount\"}},\"1\":{\"0\":{\"v\":\"A\"},\"1\":{\"v\":7}},\"2\":{\"0\":{\"v\":\"B\"},\"1\":{\"v\":9}}}},\"out\":{\"id\":\"out\",\"name\":\"Result\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{}}}}");book=f.seed(snapshot.toString());ObjectNode ws=f.runs.workspace(book,1);
        source=obj().put("runId",UUID.randomUUID().toString()).put("userId",1L).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("revision",hash(snapshot)).put("status","COMPLETED").put("goal","只读数据集").put("version",0).put("eventSeq",0);source.set("plan",obj().set("steps",arr().add(obj().put("tool","build_dataset").put("status","SUCCEEDED"))));
        f.db.update("insert into ai_agent_run(run_id,user_id,workbook_id,branch_id,request_id,request_hash,status,state_json,row_version,updated_at,created_at) values(?,?,?,?,?,?,'COMPLETED',?,0,now(3),now(3))",text(source,"runId"),1,book,source.path("branchId").asLong(),UUID.randomUUID().toString(),hash(source),source.toString());
        ObjectNode read=obj().put("sheetId","s").put("range","A1:B3").put("headerRow",true).put("includeHidden",true).put("includeFiltered",true).put("formulaPolicy","reject");new AgentTools(store).execute(source,"build_dataset",read,snapshot);
        ArrayNode list=writes.resultArtifacts(book,1);assertEquals(1,list.size());request=obj().put("entryPoint","ordinary-ai").put("requestId",UUID.randomUUID().toString()).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("activeSheetId","out").put("overwrite","empty-only");for(String key:new String[]{"loadedRevision","expectedDraftVersion","expectedBranchVersion"})request.set(key,ws.path(key.equals("expectedDraftVersion")?"draftVersion":key.equals("expectedBranchVersion")?"branchVersion":key));request.set("writeScopes",arr().add(obj().put("sheetId","out").put("range","A1:B3")));request.set("resultArtifact",list.get(0).path("selection"));request.remove("resultTarget");request.put("overwrite","confirmed").put("activeSheetId","s");request.set("writeScopes",arr().add(obj().put("sheetId","s").put("range","A1:F6")));request.set("resultSheetAuthorization",obj().put("anchorSheetId","s").put("newSheetName","Report").put("rowCount",3).put("columnCount",2));
    }
    private ObjectNode create(){return writes.create(request,1);}
    private ObjectNode claim(ObjectNode r){return writes.claim(text(r,"runId"),1,obj().put("transportVersion",2).put("clientId","ordinary-b9").set("fencingToken",r.path("fencingToken")));}
    private ObjectNode receipt(JsonNode m){ObjectNode r=obj().put("transportVersion",2).put("ok",true);for(String key:new String[]{"callId","effectId","claimToken","argsHash","fencingToken"})r.set(key,m.path(key));ArrayNode cells=arr();for(JsonNode c:m.path("cells")){ObjectNode cell=obj().put("sheetId",text(c,"sheetId")).put("row",c.path("row").asInt()).put("column",c.path("column").asInt()).put("formula","");cell.set("value",c.path("value"));cells.add(cell);}r.set("structureReadback",m.path("structureReadback"));return r;}
    private void reject(Runnable fn){try{fn.run();fail("untrusted ordinary result accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    private void mutateSource(){f.db.update("update ai_agent_run set state_json=? where run_id=?",source.toString(),text(source,"runId"));}
    private void corrupt(){f.db.update("update ai_analysis_artifact set content_json=json_set(content_json,'$.data.rows[0].Amount',999) where artifact_id=?",request.path("resultArtifact").path("resultRef").asText());}
    private void noCall(){assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_tool_call c join ai_agent_run r on r.run_id=c.run_id where r.workbook_id=? and r.run_id<>?",Integer.class,book,text(source,"runId")).intValue());assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_lease where workbook_id=? and run_id is not null",Integer.class,book).intValue());}
    private String sheetId(JsonNode r){return r.path("call").path("manifest").path("structurePatch").path("newSheetId").asText();}
    private ObjectNode verifier(JsonNode saved){ObjectNode a=obj().put("sheetId","s").put("range","A1:F6").put("kind","matches_structure");a.set("write",saved.path("lastControlledResult"));return a;}
    public void testAtomicCreateFillSaveAndSavedVerification(){ObjectNode r=create(),m=claim(r),saved=writes.receipt(text(r,"runId"),1,receipt(m));assertEquals("COMPLETED",saved.path("status").asText());JsonNode actual=parse(String.valueOf(f.status(book).get("content")));String id=sheetId(r);assertEquals(3,actual.path("sheets").size());assertEquals(9,actual.path("sheets").path(id).path("cellData").path("2").path("1").path("v").asInt());for(String old:new String[]{"s","out"})assertEquals(snapshot.path("sheets").path(old),actual.path("sheets").path(old));assertEquals("saved-controlled-result-sheet-comparison",AgentTools.verify(actual,verifier(saved)).path("method").asText());assertEquals(1,f.db.queryForObject("select count(*) from ai_agent_effect where run_id=? and status='PERSISTED'",Integer.class,text(r,"runId")).intValue());assertEquals(1,f.db.queryForObject("select count(*) from ai_agent_tool_call where run_id=?",Integer.class,text(r,"runId")).intValue());corrupt();writes.receipt(text(r,"runId"),1,receipt(m));}
    public void testStableCreationIdentityAndNoReplay(){ObjectNode first=create();assertEquals(sheetId(first),sheetId(create()));claim(first);assertFalse(claim(first).path("replayAllowed").asBoolean());ObjectNode altered=request.deepCopy();((ObjectNode)altered.path("resultSheetAuthorization")).put("newSheetName","Other");reject(()->writes.create(altered,1));}
    public void testAuthorizationScopeDimensionsAndNameDenied(){ObjectNode original=request.deepCopy();request.remove("resultSheetAuthorization");reject(()->create());request=original.deepCopy();request.set("writeScopes",arr().add(obj().put("sheetId","s").put("range","A1:B3")));reject(()->create());request=original.deepCopy();((ObjectNode)request.path("resultSheetAuthorization")).put("rowCount",4);reject(()->create());request=original.deepCopy();((ObjectNode)request.path("resultSheetAuthorization")).put("newSheetName","Source");reject(()->create());noCall();}
    public void testMixedTargetOrUnconfirmedCreateDenied(){request.set("resultTarget",obj().put("sheetId","out").put("range","A1:B3"));reject(()->create());request.remove("resultTarget");request.put("overwrite","empty-only");reject(()->create());noCall();}
    public void testNewSheetGateIndependentAndDefaultClosed() throws Exception {A1TestFixture.inject(writes,"b9ResultSheetEnabled",false);assertTrue(writes.resultWritesEnabled());assertFalse(writes.resultSheetWritesEnabled());reject(()->create());noCall();}
    public void testSourceChangedBeforeClaimNoEmptySheetSaved(){ObjectNode r=create();corrupt();reject(()->claim(r));assertNull(f.status(book).get("workingState"));assertEquals(2,parse(String.valueOf(f.status(book).get("content"))).path("sheets").size());}
    public void testSourceChangedAfterClaimNoEmptySheetSaved(){ObjectNode r=create(),m=claim(r);corrupt();reject(()->writes.receipt(text(r,"runId"),1,receipt(m)));assertNull(f.status(book).get("workingState"));}
    public void testWrongReadbackAndLateClosedGateCannotSave() throws Exception {ObjectNode r=create(),m=claim(r),bad=receipt(m);((ObjectNode)bad.path("structureReadback")).put("workbookDigest","forged");reject(()->writes.receipt(text(r,"runId"),1,bad));A1TestFixture.inject(writes,"b9ResultSheetEnabled",false);reject(()->writes.receipt(text(r,"runId"),1,receipt(m)));assertNull(f.status(book).get("workingState"));}
    public void testFailedReceiptRemainsUnknownAndUnpersisted(){ObjectNode r=create(),m=claim(r),bad=receipt(m);bad.remove("structureReadback");bad.put("ok",false).put("error","partial local insert");ObjectNode paused=writes.receipt(text(r,"runId"),1,bad);assertEquals("PAUSED",paused.path("status").asText());assertNull(f.status(book).get("workingState"));reject(()->claim(paused));}
    public void testSavedVerifierRejectsValuesProvenanceAndNeighborTamper(){ObjectNode r=create(),m=claim(r),saved=writes.receipt(text(r,"runId"),1,receipt(m));ObjectNode actual=(ObjectNode)parse(String.valueOf(f.status(book).get("content"))),changed=actual.deepCopy();((ObjectNode)changed.path("sheets").path(sheetId(r)).path("cellData").path("2").path("1")).put("v",999);reject(()->AgentTools.verify(changed,verifier(saved)));ObjectNode forged=saved.deepCopy();((ObjectNode)forged.path("lastControlledResult").path("executedChange").path("resultSource")).put("dataDigest","forged");reject(()->AgentTools.verify(actual,verifier(forged)));}
    public void testPlanAdmissionNeedsExactAuthorizationAndCompleteVerifier(){ObjectNode p=B9ResultPlanTest.plan(),run=obj();run.set("resultSheetAuthorization",request.path("resultSheetAuthorization"));ObjectNode w=obj().put("overwrite","confirmed");w.set("dataset",obj().put("$step","D"));w.set("newSheet",request.path("resultSheetAuthorization"));((ObjectNode)p.path("steps").get(1)).set("inputBindings",w);ObjectNode v=(ObjectNode)p.path("steps").get(2).path("inputBindings");v.put("sheetId","s").put("range","A1:F6").put("kind","matches_structure");JsonNode copy=ResultPlan.admissionCopy(p,true,true,run);AgentPlan.validateForRun(copy,snapshot,request.path("writeScopes"),"s",true,true,false,false,false,false,false,true,false,false,false);assertEquals("write_result",p.path("steps").get(1).path("tool").asText());reject(()->ResultPlan.admissionCopy(p,true,false,run));reject(()->ResultPlan.admissionCopy(p,true,true,obj()));((ObjectNode)w.path("newSheet")).put("newSheetName","forged");ObjectNode authorization=run.deepCopy();((ObjectNode)authorization.path("resultSheetAuthorization")).put("newSheetName","Other");reject(()->ResultPlan.admissionCopy(p,true,true,authorization));}
    public void testFormulaOrBudgetWorkbookCannotCreateResultSheet(){ObjectNode formula=snapshot.deepCopy();((ObjectNode)formula.path("sheets").path("s").path("cellData").path("1").path("1")).put("f","=1+6");reject(()->ResultSheetManifest.preview(formula,request.path("resultSheetAuthorization"),request.path("writeScopes")));ObjectNode budget=request.path("resultSheetAuthorization").deepCopy();budget.put("rowCount",100).put("columnCount",100);reject(()->ResultSheetManifest.preview(snapshot,budget,request.path("writeScopes")));noCall();}
}
